import assert from 'node:assert/strict';import fs from 'node:fs';import {loadRepositoryModule as load} from './load-player-catalogue.mjs';
const {officialChallenges}=load('lib/sbcCatalog.ts');const {pointsSegments,pointsPlans,pointsPlanValid}=load('lib/sbcVerified.ts');const {rewardKind}=load('lib/sbcBrowse.ts');const {PLAYERS}=load('lib/fcPlayers.ts');assert.equal(PLAYERS.length,20200);
for(const id of ['sbc-showdown-carlos-20261028','sbc-showdown-ruben-20261028','sbc-ligue-arkema-upgrade-20261028','sbc-bundesliga-frauen-upgrade-20261028','sbc-upgrade-80x5-20261027']){assert(officialChallenges.find(x=>x.id===id));const segments=pointsSegments(id);assert.equal(segments.length,id.includes('upgrade-20261028')?2:1);for(const segment of segments)for(const platform of ['ps5','pc']){const plans=pointsPlans(segment,platform);assert(plans.length>2,id);assert(plans.some(p=>p.key.startsWith('verified-')));for(const plan of plans)assert(pointsPlanValid(segment,plan,platform));assert(pointsPlans(segment,platform,Math.floor(segment.target/2)).length);}}
for(const [id,file] of [['sbc-showdown-carlos-20261028','carlos-50590296.png'],['sbc-showdown-ruben-20261028','ruben-50545314.png']]){assert.equal(rewardKind(officialChallenges.find(x=>x.id===id)),'players');const img=fs.readFileSync('assets/images/sbc-rewards/'+file);assert.equal(img.subarray(0,8).toString('hex'),'89504e470d0a1a0a');assert.equal(img.readUInt32BE(16),300);assert.equal(img.readUInt32BE(20),419);assert(fs.readFileSync('components/SbcRewardVisual.tsx','utf8').includes(file));}for(const id of ['sbc-boo-hoo-20261028','sbc-upgrade-79x3-20261026'])assert(officialChallenges.find(x=>x.id===id));console.log('PASS: new SBC entries, exact card art, platform solutions, partial progress and 20,200 cards.');
